  j constant jsonb := $j$[
{"id":"9bf93cc1-48c7-4271-98a2-a18b36099423","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"es","slug":"espaguetis-a-la-carbonara","public_path":"/espaguetis-a-la-carbonara","source_url":null,"title":"Espaguetis a la carbonara","excerpt":"Espaguetis a la carbonara con guanciale crujiente, pecorino romano, yemas, huevo y pimienta negra, sin nata. Para 4 personas, listos en 35 minutos.","summary":"La carbonara es una pasta romana que se liga con yemas, huevo, pecorino romano y el agua de cocción, sin nata. El guanciale se dora en la sartén sin aceite y los espaguetis se mezclan con la crema de huevo fuera del fuego.\n\nSe cuece la pasta unos 9 minutos, se dora el guanciale 8 minutos y se termina la salsa en 1 minuto, sin fuego, para que el huevo no cuaje. Rinde 4 porciones.","category":"Platos principales","difficulty":"Media","course":"Plato principal","cuisine":"Italiana","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["espaguetis a la carbonara","receta de carbonara","carbonara original","carbonara sin nata","pasta carbonara","cómo hacer carbonara","guanciale y pecorino"],"ingredients":[{"name":"yemas de huevo","amount":"4","unit":"","group":"Para la salsa"},{"name":"huevo entero","amount":"1","unit":"","group":"Para la salsa"},{"name":"pecorino romano rallado","amount":"80","unit":"g","group":"Para la salsa"},{"name":"pimienta negra recién molida","amount":"1","unit":"cucharadita","group":"Para la salsa"},{"name":"espaguetis","amount":"400","unit":"g","group":"Para la pasta"},{"name":"guanciale en tiras","amount":"150","unit":"g","group":"Para la pasta"},{"name":"agua","amount":"4","unit":"l","group":"Para la pasta"},{"name":"sal gruesa","amount":"40","unit":"g","group":"Para la pasta"}],"steps":[{"title":"Prepara los ingredientes","content":"Corta 150 g de guanciale en tiras de 1 cm y ralla 80 g de pecorino romano. Separa 4 yemas y ten a mano 1 huevo entero, la pimienta y 400 g de espaguetis.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"Espaguetis a la carbonara: Prepara los ingredientes"},{"title":"Bate la salsa","content":"En un bol bate 4 yemas, 1 huevo entero, 80 g de pecorino romano y 1 cucharadita de pimienta negra recién molida hasta obtener una crema espesa.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"Espaguetis a la carbonara: Bate la salsa"},{"title":"Cuece los espaguetis","content":"Hierve 4 litros de agua con 40 g de sal gruesa, echa 400 g de espaguetis y cuécelos unos 9 minutos, hasta que estén al dente.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"Espaguetis a la carbonara: Cuece los espaguetis"},{"title":"Dora el guanciale","content":"Mientras tanto, pon el guanciale en una sartén grande fría, sin aceite, a fuego medio-bajo y dóralo 8 minutos, hasta que esté crujiente y suelte la grasa. Apaga el fuego.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"Espaguetis a la carbonara: Dora el guanciale"},{"title":"Reserva agua de cocción","content":"Antes de escurrir, reserva 1 vaso (unos 200 ml) del agua de cocción y escurre los espaguetis.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"Espaguetis a la carbonara: Reserva agua de cocción"},{"title":"Mezcla con el guanciale","content":"Pasa los espaguetis a la sartén con el guanciale, fuera del fuego, y remueve 30 segundos para que se impregnen de grasa.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"Espaguetis a la carbonara: Mezcla con el guanciale"},{"title":"Añade la salsa","content":"Vierte la crema de huevo y 3 cucharadas del agua reservada, y mezcla con pinzas 1 minuto, sin fuego, hasta que quede cremosa y no cuaje.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"Espaguetis a la carbonara: Añade la salsa"},{"title":"Sirve","content":"Sirve enseguida en platos hondos y termina con más pecorino y pimienta negra.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"Espaguetis a la carbonara: Sirve"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"Espaguetis a la carbonara"}],"notes":"No añadas nata: la cremosidad viene de la yema, el queso y el agua de la pasta. La sartén debe estar fuera del fuego al añadir el huevo para que no cuaje; si la salsa queda espesa, añade más agua de cocción poco a poco. Si no encuentras guanciale, puedes usar panceta curada, aunque el sabor cambia. Lleva huevo poco cocinado: usa huevos frescos, sírvela enseguida y no la prepares para embarazadas, niños pequeños, personas mayores o inmunodeprimidas.","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 400 g de espaguetis secos, 150 g de guanciale, 68 g de yema (4 yemas), 50 g de huevo entero, 80 g de pecorino romano, 2 g de pimienta y 4 g de sal (aprox. el 10 % de los 40 g de sal del agua de cocción). El agua no se cuenta.","note":"Estimación por porción. El guanciale se calcula con panceta curada cruda y el pecorino romano con queso romano, como valores de referencia. Se cuenta toda la grasa del guanciale, aunque parte quede en la sartén, y el sodio depende del guanciale, del queso y de la sal que absorba la pasta.","inputs":[{"fdc_id":"169736","description":"Pasta, dry, enriched (400 g de espaguetis secos)","grams":400,"per100":{"calories":371,"protein_g":13.04,"carbs_g":74.67,"fat_g":1.51,"saturated_fat_g":0.32,"fiber_g":3.2,"sodium_mg":6}},{"fdc_id":"168277","description":"Pork, cured, bacon, raw (proxy del guanciale)","grams":150,"per100":{"calories":417,"protein_g":12.62,"carbs_g":1.28,"fat_g":40.14,"saturated_fat_g":13.85,"fiber_g":0,"sodium_mg":1717}},{"fdc_id":"172184","description":"Egg, yolk, raw, fresh (4 yemas de unos 17 g)","grams":68,"per100":{"calories":322,"protein_g":15.86,"carbs_g":3.59,"fat_g":26.54,"saturated_fat_g":9.55,"fiber_g":0,"sodium_mg":48}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh (1 huevo de unos 50 g)","grams":50,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"171249","description":"Cheese, romano (proxy del pecorino romano)","grams":80,"per100":{"calories":387,"protein_g":31.8,"carbs_g":3.63,"fat_g":26.94,"saturated_fat_g":17.23,"fiber_g":0,"sodium_mg":1862}},{"fdc_id":"170931","description":"Spices, pepper, black","grams":2,"per100":{"calories":251,"protein_g":10.39,"carbs_g":63.95,"fat_g":3.26,"saturated_fat_g":0.98,"fiber_g":25.3,"sodium_mg":20}},{"fdc_id":"173468","description":"Salt, table (4 g de los 40 g de sal del agua de cocción)","grams":4,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}}]},"seo":{"title":"Espaguetis a la carbonara sin nata | Manual de Cocina","description":"Espaguetis a la carbonara con guanciale, pecorino romano, yemas y pimienta, sin nata. Para 4 personas, listos en 35 minutos. Receta paso a paso.","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"¿Lleva nata la carbonara?","a":"No. La cremosidad sale de las yemas, el pecorino romano y un poco del agua de cocción de la pasta."},{"q":"¿Por qué no se cuaja el huevo?","a":"Porque la mezcla se hace fuera del fuego y con agua de cocción: el calor de la pasta y de la sartén basta para ligar la salsa sin cuajar el huevo de golpe."},{"q":"¿Qué puedo usar si no hay guanciale?","a":"Puedes usar panceta curada en tiras. El sabor es algo más ahumado y menos dulce, pero el método es el mismo."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f7b0ba63-3bf6-5634-9010-81c989c7bf3c","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"de","slug":"spaghetti-carbonara-rezept","public_path":"/de/spaghetti-carbonara-rezept","source_url":null,"title":"Spaghetti Carbonara","excerpt":"Spaghetti Carbonara mit knusprigem Guanciale, Pecorino Romano, Eigelb, Ei und schwarzem Pfeffer, ohne Sahne. Für 4 Personen, fertig in 35 Minuten.","summary":"Carbonara ist eine römische Pasta, die mit Eigelb, Ei, Pecorino Romano und Nudelwasser gebunden wird, ohne Sahne. Der Guanciale wird ohne Öl in der Pfanne knusprig gebraten, und die Spaghetti werden vom Herd genommen mit der Eiercreme vermengt.\n\nDie Pasta kocht etwa 9 Minuten, der Guanciale brät 8 Minuten, und die Sauce wird in 1 Minute ohne Hitze fertig, damit das Ei nicht stockt. Ergibt 4 Portionen.","category":"Hauptgerichte","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Italienisch","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["Spaghetti Carbonara","Carbonara Rezept","Carbonara Original","Carbonara ohne Sahne","Pasta Carbonara","Carbonara selber machen","Guanciale und Pecorino"],"ingredients":[{"name":"Eigelb","amount":"4","unit":"","group":"Für die Sauce"},{"name":"Ei (ganz)","amount":"1","unit":"","group":"Für die Sauce"},{"name":"geriebener Pecorino Romano","amount":"80","unit":"g","group":"Für die Sauce"},{"name":"frisch gemahlener schwarzer Pfeffer","amount":"1","unit":"Teelöffel","group":"Für die Sauce"},{"name":"Spaghetti","amount":"400","unit":"g","group":"Für die Pasta"},{"name":"Guanciale, in Streifen","amount":"150","unit":"g","group":"Für die Pasta"},{"name":"Wasser","amount":"4","unit":"l","group":"Für die Pasta"},{"name":"grobes Salz","amount":"40","unit":"g","group":"Für die Pasta"}],"steps":[{"title":"Zutaten vorbereiten","content":"150 g Guanciale in 1 cm breite Streifen schneiden und 80 g Pecorino Romano reiben. 4 Eigelb trennen und 1 ganzes Ei, den Pfeffer und 400 g Spaghetti bereitstellen.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"Spaghetti Carbonara: Zutaten vorbereiten"},{"title":"Sauce verrühren","content":"4 Eigelb, 1 ganzes Ei, 80 g Pecorino Romano und 1 Teelöffel frisch gemahlenen schwarzen Pfeffer in einer Schüssel zu einer dicken Creme verrühren.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"Spaghetti Carbonara: Sauce verrühren"},{"title":"Spaghetti kochen","content":"4 Liter Wasser mit 40 g grobem Salz aufkochen, 400 g Spaghetti hineingeben und etwa 9 Minuten bissfest kochen.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"Spaghetti Carbonara: Spaghetti kochen"},{"title":"Guanciale braten","content":"Währenddessen den Guanciale ohne Öl in einer großen kalten Pfanne bei mittlerer bis niedriger Hitze 8 Minuten braten, bis er knusprig ist und sein Fett abgegeben hat. Den Herd ausschalten.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"Spaghetti Carbonara: Guanciale braten"},{"title":"Kochwasser auffangen","content":"Vor dem Abgießen 1 Glas (etwa 200 ml) Kochwasser abschöpfen und die Spaghetti abgießen.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"Spaghetti Carbonara: Kochwasser auffangen"},{"title":"Mit dem Guanciale mischen","content":"Die Spaghetti vom Herd genommen in die Pfanne mit dem Guanciale geben und 30 Sekunden durchschwenken, damit sie das Fett aufnehmen.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"Spaghetti Carbonara: Mit dem Guanciale mischen"},{"title":"Sauce zugeben","content":"Die Eiercreme und 3 Esslöffel des Kochwassers zugeben und 1 Minute mit der Zange vermengen, ohne Hitze, bis die Sauce cremig ist und nicht stockt.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"Spaghetti Carbonara: Sauce zugeben"},{"title":"Servieren","content":"Sofort in tiefen Tellern servieren und mit mehr Pecorino und schwarzem Pfeffer bestreuen.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"Spaghetti Carbonara: Servieren"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"Spaghetti Carbonara"}],"notes":"Keine Sahne verwenden: die Cremigkeit kommt vom Eigelb, vom Käse und vom Nudelwasser. Die Pfanne muss beim Zugeben des Eis vom Herd sein, damit es nicht stockt; wird die Sauce zu dick, nach und nach mehr Kochwasser zugeben. Ohne Guanciale lässt sich gereifter Pancetta verwenden, der Geschmack ändert sich dann etwas. Das Gericht enthält nur schwach gegartes Ei: frische Eier verwenden, sofort servieren und nicht für Schwangere, Kleinkinder, ältere oder immungeschwächte Personen zubereiten.","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 400 g trockene Spaghetti, 150 g Guanciale, 68 g Eigelb (4 Eigelb), 50 g ganzes Ei, 80 g Pecorino Romano, 2 g Pfeffer und 4 g Salz (etwa 10 % der 40 g Salz im Kochwasser). Das Wasser wird nicht gezählt.","note":"Schätzung pro Portion. Guanciale wird mit rohem gepökeltem Bauchspeck und Pecorino Romano mit Romano-Käse als Referenzwerten berechnet. Das gesamte Fett des Guanciale wird gezählt, auch wenn ein Teil in der Pfanne bleibt, und das Natrium hängt von Guanciale, Käse und dem von der Pasta aufgenommenen Salz ab."},"seo":{"title":"Spaghetti Carbonara ohne Sahne | Manual de Cocina","description":"Spaghetti Carbonara mit Guanciale, Pecorino Romano, Eigelb und Pfeffer, ohne Sahne. Für 4 Personen, fertig in 35 Minuten. Rezept Schritt für Schritt.","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"Kommt Sahne in die Carbonara?","a":"Nein. Die Cremigkeit kommt vom Eigelb, vom Pecorino Romano und von etwas Nudelwasser."},{"q":"Warum stockt das Ei nicht?","a":"Weil alles vom Herd genommen und mit Nudelwasser vermengt wird: Die Wärme der Pasta und der Pfanne reicht, um die Sauce zu binden, ohne das Ei auf einmal zu stocken."},{"q":"Was kann ich ohne Guanciale verwenden?","a":"Gereifter Pancetta in Streifen. Der Geschmack ist etwas rauchiger und weniger mild, die Methode bleibt gleich."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"6ffc1ad5-75d3-519e-a8b6-7aaa4110aa2c","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"en","slug":"spaghetti-carbonara","public_path":"/en/spaghetti-carbonara","source_url":null,"title":"Spaghetti Carbonara","excerpt":"Spaghetti carbonara with crisp guanciale, pecorino romano, egg yolks, egg and black pepper, no cream. Serves 4, ready in 35 minutes.","summary":"Carbonara is a Roman pasta bound with egg yolks, egg, pecorino romano and pasta water, with no cream. The guanciale crisps in the pan with no oil, and the spaghetti is tossed with the egg cream off the heat.\n\nThe pasta cooks about 9 minutes, the guanciale 8 minutes, and the sauce finishes in 1 minute with no heat so the egg does not scramble. It serves 4.","category":"Main dishes","difficulty":"Medium","course":"Main dish","cuisine":"Italian","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["spaghetti carbonara","carbonara recipe","authentic carbonara","carbonara without cream","pasta carbonara","how to make carbonara","guanciale and pecorino"],"ingredients":[{"name":"egg yolks","amount":"4","unit":"","group":"For the sauce"},{"name":"whole egg","amount":"1","unit":"","group":"For the sauce"},{"name":"grated pecorino romano","amount":"80","unit":"g","group":"For the sauce"},{"name":"freshly ground black pepper","amount":"1","unit":"teaspoon","group":"For the sauce"},{"name":"spaghetti","amount":"400","unit":"g","group":"For the pasta"},{"name":"guanciale, cut into strips","amount":"150","unit":"g","group":"For the pasta"},{"name":"water","amount":"4","unit":"l","group":"For the pasta"},{"name":"coarse salt","amount":"40","unit":"g","group":"For the pasta"}],"steps":[{"title":"Prepare the ingredients","content":"Cut 150 g guanciale into strips about 1 cm wide and grate 80 g pecorino romano. Separate 4 yolks and have ready 1 whole egg, the pepper and 400 g spaghetti.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"Spaghetti Carbonara: Prepare the ingredients"},{"title":"Whisk the sauce","content":"In a bowl whisk 4 yolks, 1 whole egg, 80 g pecorino romano and 1 teaspoon freshly ground black pepper into a thick cream.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"Spaghetti Carbonara: Whisk the sauce"},{"title":"Boil the spaghetti","content":"Bring 4 liters of water with 40 g coarse salt to a boil, add 400 g spaghetti and cook about 9 minutes, until al dente.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"Spaghetti Carbonara: Boil the spaghetti"},{"title":"Crisp the guanciale","content":"Meanwhile, put the guanciale in a large cold pan with no oil over medium-low heat and cook 8 minutes, until crisp and the fat has rendered. Turn off the heat.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"Spaghetti Carbonara: Crisp the guanciale"},{"title":"Save some pasta water","content":"Before draining, set aside 1 cup (about 200 ml) of the cooking water, then drain the spaghetti.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"Spaghetti Carbonara: Save some pasta water"},{"title":"Toss with the guanciale","content":"Add the spaghetti to the pan with the guanciale, off the heat, and toss for 30 seconds so it coats in the fat.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"Spaghetti Carbonara: Toss with the guanciale"},{"title":"Add the sauce","content":"Pour in the egg cream and 3 tablespoons of the reserved water and toss with tongs for 1 minute, off the heat, until creamy and not scrambled.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"Spaghetti Carbonara: Add the sauce"},{"title":"Serve","content":"Serve right away in shallow bowls and finish with more pecorino and black pepper.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"Spaghetti Carbonara: Serve"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"Spaghetti Carbonara"}],"notes":"Do not add cream: the creaminess comes from the yolks, the cheese and the pasta water. The pan must be off the heat when the egg goes in so it does not scramble; if the sauce is too thick, add more cooking water a little at a time. If you cannot find guanciale, you can use cured pancetta, though the flavor changes. It contains lightly cooked egg: use fresh eggs, serve it right away and do not make it for pregnant women, young children, older adults or people with weakened immune systems.","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g multiplied by the ingredient weights and divided by 4 servings. It uses 400 g dry spaghetti, 150 g guanciale, 68 g egg yolk (4 yolks), 50 g whole egg, 80 g pecorino romano, 2 g pepper and 4 g salt (about 10% of the 40 g of salt in the cooking water). The water is not counted.","note":"Estimate per serving. Guanciale is calculated with raw cured bacon and pecorino romano with romano cheese, as reference values. All the guanciale fat is counted even though some stays in the pan, and sodium depends on the guanciale, the cheese and the salt the pasta absorbs."},"seo":{"title":"Spaghetti carbonara without cream | Manual de Cocina","description":"Spaghetti carbonara with guanciale, pecorino romano, egg yolks and pepper, no cream. Serves 4, ready in 35 minutes. Step-by-step recipe.","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"Does carbonara have cream?","a":"No. The creaminess comes from the egg yolks, the pecorino romano and a little of the pasta cooking water."},{"q":"Why does the egg not scramble?","a":"Because everything is mixed off the heat with pasta water: the warmth of the pasta and the pan is enough to bind the sauce without setting the egg all at once."},{"q":"What can I use if I have no guanciale?","a":"You can use cured pancetta in strips. The flavor is a little smokier and less sweet, but the method is the same."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b5ace2c4-c22f-522b-9b59-09a746bccc2d","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"fr","slug":"spaghetti-carbonara","public_path":"/fr/spaghetti-carbonara","source_url":null,"title":"Spaghetti carbonara","excerpt":"Spaghetti carbonara avec guanciale croustillant, pecorino romano, jaunes d’œufs, œuf et poivre noir, sans crème. Pour 4 personnes, prêts en 35 minutes.","summary":"La carbonara est une pâte romaine liée avec des jaunes d’œufs, un œuf, du pecorino romano et de l’eau de cuisson, sans crème. Le guanciale croustille dans la poêle sans huile, et les spaghetti sont mélangés à la crème d’œufs hors du feu.\n\nLes pâtes cuisent environ 9 minutes, le guanciale 8 minutes, et la sauce se termine en 1 minute sans feu pour que l’œuf ne coagule pas. Pour 4 personnes.","category":"Plats principaux","difficulty":"Moyenne","course":"Plat principal","cuisine":"Italienne","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["spaghetti carbonara","recette de carbonara","carbonara authentique","carbonara sans crème","pâtes carbonara","comment faire une carbonara","guanciale et pecorino"],"ingredients":[{"name":"jaunes d’œufs","amount":"4","unit":"","group":"Pour la sauce"},{"name":"œuf entier","amount":"1","unit":"","group":"Pour la sauce"},{"name":"pecorino romano râpé","amount":"80","unit":"g","group":"Pour la sauce"},{"name":"poivre noir fraîchement moulu","amount":"1","unit":"cuillère à café","group":"Pour la sauce"},{"name":"spaghetti","amount":"400","unit":"g","group":"Pour les pâtes"},{"name":"guanciale en lamelles","amount":"150","unit":"g","group":"Pour les pâtes"},{"name":"eau","amount":"4","unit":"l","group":"Pour les pâtes"},{"name":"gros sel","amount":"40","unit":"g","group":"Pour les pâtes"}],"steps":[{"title":"Préparer les ingrédients","content":"Couper 150 g de guanciale en lamelles d’environ 1 cm et râper 80 g de pecorino romano. Séparer 4 jaunes et préparer 1 œuf entier, le poivre et 400 g de spaghetti.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"Spaghetti carbonara: Préparer les ingrédients"},{"title":"Battre la sauce","content":"Dans un bol, battre 4 jaunes, 1 œuf entier, 80 g de pecorino romano et 1 cuillère à café de poivre noir fraîchement moulu jusqu’à obtenir une crème épaisse.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"Spaghetti carbonara: Battre la sauce"},{"title":"Cuire les spaghetti","content":"Porter à ébullition 4 litres d’eau avec 40 g de gros sel, ajouter 400 g de spaghetti et cuire environ 9 minutes, jusqu’à ce qu’ils soient al dente.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"Spaghetti carbonara: Cuire les spaghetti"},{"title":"Faire croustiller le guanciale","content":"Pendant ce temps, mettre le guanciale dans une grande poêle froide, sans huile, à feu moyen-doux et le cuire 8 minutes, jusqu’à ce qu’il soit croustillant et ait rendu sa graisse. Éteindre le feu.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"Spaghetti carbonara: Faire croustiller le guanciale"},{"title":"Réserver de l’eau de cuisson","content":"Avant d’égoutter, réserver 1 verre (environ 200 ml) d’eau de cuisson, puis égoutter les spaghetti.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"Spaghetti carbonara: Réserver de l’eau de cuisson"},{"title":"Mélanger avec le guanciale","content":"Verser les spaghetti dans la poêle avec le guanciale, hors du feu, et les faire sauter 30 secondes pour qu’ils s’imprègnent de graisse.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"Spaghetti carbonara: Mélanger avec le guanciale"},{"title":"Ajouter la sauce","content":"Verser la crème d’œufs et 3 cuillères à soupe de l’eau réservée et mélanger à la pince 1 minute, hors du feu, jusqu’à ce que la sauce soit onctueuse sans coaguler.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"Spaghetti carbonara: Ajouter la sauce"},{"title":"Servir","content":"Servir aussitôt dans des assiettes creuses et terminer avec encore du pecorino et du poivre noir.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"Spaghetti carbonara: Servir"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"Spaghetti carbonara"}],"notes":"Ne pas ajouter de crème : l’onctuosité vient des jaunes, du fromage et de l’eau de cuisson. La poêle doit être hors du feu quand on ajoute l’œuf pour qu’il ne coagule pas ; si la sauce est trop épaisse, ajouter un peu plus d’eau de cuisson petit à petit. À défaut de guanciale, on peut utiliser de la pancetta, mais le goût change. Cette recette contient de l’œuf peu cuit : utiliser des œufs frais, servir aussitôt et ne pas la préparer pour des femmes enceintes, de jeunes enfants, des personnes âgées ou immunodéprimées.","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 400 g de spaghetti secs, 150 g de guanciale, 68 g de jaune d’œuf (4 jaunes), 50 g d’œuf entier, 80 g de pecorino romano, 2 g de poivre et 4 g de sel (environ 10 % des 40 g de sel de l’eau de cuisson). L’eau n’est pas comptée.","note":"Estimation par portion. Le guanciale est calculé avec du lard fumé cru et le pecorino romano avec du fromage romano, comme valeurs de référence. Toute la graisse du guanciale est comptée, même si une partie reste dans la poêle, et le sodium dépend du guanciale, du fromage et du sel absorbé par les pâtes."},"seo":{"title":"Spaghetti carbonara sans crème | Manual de Cocina","description":"Spaghetti carbonara avec guanciale, pecorino romano, jaunes d’œufs et poivre, sans crème. Pour 4 personnes, prêts en 35 minutes. Recette pas à pas.","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"La carbonara contient-elle de la crème ?","a":"Non. L’onctuosité vient des jaunes d’œufs, du pecorino romano et d’un peu d’eau de cuisson des pâtes."},{"q":"Pourquoi l’œuf ne coagule-t-il pas ?","a":"Parce que tout se mélange hors du feu avec de l’eau de cuisson : la chaleur des pâtes et de la poêle suffit à lier la sauce sans faire coaguler l’œuf d’un coup."},{"q":"Que mettre à défaut de guanciale ?","a":"On peut utiliser de la pancetta en lamelles. Le goût est un peu plus fumé et moins doux, mais la méthode est la même."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"7baa9ef9-172a-5cfd-ba4f-899f7c345fce","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"it","slug":"spaghetti-alla-carbonara","public_path":"/it/spaghetti-alla-carbonara","source_url":null,"title":"Spaghetti alla carbonara","excerpt":"Spaghetti alla carbonara con guanciale croccante, pecorino romano, tuorli, uovo e pepe nero, senza panna. Per 4 persone, pronti in 35 minuti.","summary":"La carbonara è una pasta romana legata con tuorli, uovo, pecorino romano e acqua di cottura, senza panna. Il guanciale si rosola in padella senza olio e gli spaghetti si mescolano alla crema di uova fuori dal fuoco.\n\nLa pasta cuoce circa 9 minuti, il guanciale 8 minuti e la salsa si completa in 1 minuto, senza fuoco, perché l’uovo non si rapprenda. Per 4 porzioni.","category":"Secondi piatti","difficulty":"Media","course":"Primo piatto","cuisine":"Italiana","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["spaghetti alla carbonara","ricetta carbonara","carbonara originale","carbonara senza panna","pasta alla carbonara","come fare la carbonara","guanciale e pecorino"],"ingredients":[{"name":"tuorli d’uovo","amount":"4","unit":"","group":"Per la salsa"},{"name":"uovo intero","amount":"1","unit":"","group":"Per la salsa"},{"name":"pecorino romano grattugiato","amount":"80","unit":"g","group":"Per la salsa"},{"name":"pepe nero macinato al momento","amount":"1","unit":"cucchiaino","group":"Per la salsa"},{"name":"spaghetti","amount":"400","unit":"g","group":"Per la pasta"},{"name":"guanciale a listarelle","amount":"150","unit":"g","group":"Per la pasta"},{"name":"acqua","amount":"4","unit":"l","group":"Per la pasta"},{"name":"sale grosso","amount":"40","unit":"g","group":"Per la pasta"}],"steps":[{"title":"Prepara gli ingredienti","content":"Taglia 150 g di guanciale a listarelle di circa 1 cm e gratta 80 g di pecorino romano. Separa 4 tuorli e tieni pronti 1 uovo intero, il pepe e 400 g di spaghetti.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"Spaghetti alla carbonara: Prepara gli ingredienti"},{"title":"Sbatti la salsa","content":"In una ciotola sbatti 4 tuorli, 1 uovo intero, 80 g di pecorino romano e 1 cucchiaino di pepe nero macinato al momento fino a ottenere una crema densa.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"Spaghetti alla carbonara: Sbatti la salsa"},{"title":"Cuoci gli spaghetti","content":"Porta a bollore 4 litri di acqua con 40 g di sale grosso, versa 400 g di spaghetti e cuocili circa 9 minuti, fino a quando sono al dente.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"Spaghetti alla carbonara: Cuoci gli spaghetti"},{"title":"Rosola il guanciale","content":"Nel frattempo metti il guanciale in una padella grande fredda, senza olio, a fuoco medio-basso e cuocilo 8 minuti, finché è croccante e ha rilasciato il grasso. Spegni il fuoco.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"Spaghetti alla carbonara: Rosola il guanciale"},{"title":"Conserva l’acqua di cottura","content":"Prima di scolare, metti da parte 1 bicchiere (circa 200 ml) di acqua di cottura, poi scola gli spaghetti.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"Spaghetti alla carbonara: Conserva l’acqua di cottura"},{"title":"Unisci al guanciale","content":"Versa gli spaghetti nella padella con il guanciale, fuori dal fuoco, e saltali 30 secondi perché si insaporiscano di grasso.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"Spaghetti alla carbonara: Unisci al guanciale"},{"title":"Aggiungi la salsa","content":"Versa la crema di uova e 3 cucchiai dell’acqua messa da parte e mescola con le pinze per 1 minuto, senza fuoco, finché la salsa è cremosa e non si rapprende.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"Spaghetti alla carbonara: Aggiungi la salsa"},{"title":"Servi","content":"Servi subito in piatti fondi e completa con altro pecorino e pepe nero.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"Spaghetti alla carbonara: Servi"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"Spaghetti alla carbonara"}],"notes":"Non aggiungere panna: la cremosità viene dai tuorli, dal formaggio e dall’acqua di cottura. La padella deve essere fuori dal fuoco quando aggiungi l’uovo perché non si rapprenda; se la salsa è troppo densa, aggiungi altra acqua di cottura poco alla volta. Se non trovi il guanciale, puoi usare pancetta stagionata, ma il sapore cambia. Contiene uovo poco cotto: usa uova fresche, servi subito e non prepararla per donne in gravidanza, bambini piccoli, anziani o persone immunodepresse.","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per il peso degli ingredienti e divisi per 4 porzioni. Si usano 400 g di spaghetti secchi, 150 g di guanciale, 68 g di tuorlo (4 tuorli), 50 g di uovo intero, 80 g di pecorino romano, 2 g di pepe e 4 g di sale (circa il 10 % dei 40 g di sale dell’acqua di cottura). L’acqua non è conteggiata.","note":"Stima per porzione. Il guanciale è calcolato con pancetta stagionata cruda e il pecorino romano con formaggio romano, come valori di riferimento. Si conta tutto il grasso del guanciale, anche se una parte resta nella padella, e il sodio dipende da guanciale, formaggio e sale assorbito dalla pasta."},"seo":{"title":"Spaghetti alla carbonara senza panna | Manual de Cocina","description":"Spaghetti alla carbonara con guanciale, pecorino romano, tuorli e pepe, senza panna. Per 4 persone, pronti in 35 minuti. Ricetta passo passo.","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"La carbonara contiene la panna?","a":"No. La cremosità viene dai tuorli, dal pecorino romano e da un po’ di acqua di cottura della pasta."},{"q":"Perché l’uovo non si rapprende?","a":"Perché tutto si mescola fuori dal fuoco e con acqua di cottura: il calore della pasta e della padella basta a legare la salsa senza rapprendere l’uovo tutto insieme."},{"q":"Cosa posso usare se non ho il guanciale?","a":"Puoi usare pancetta stagionata a listarelle. Il sapore è un po’ più affumicato e meno dolce, ma il metodo è lo stesso."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"d1ee47b2-3878-5314-ad7f-6aa66a31f013","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"ja","slug":"カルボナーラ","public_path":"/ja/カルボナーラ","source_url":null,"title":"スパゲッティ・カルボナーラ","excerpt":"カリカリのグアンチャーレ、ペコリーノ・ロマーノ、卵黄、卵、黒こしょうで作る生クリームなしのスパゲッティ・カルボナーラ。4人分、35分で完成。","summary":"カルボナーラは、卵黄、卵、ペコリーノ・ロマーノ、ゆで汁でソースをまとめる、生クリームを使わないローマ風パスタです。グアンチャーレは油なしでフライパンで焼き、スパゲッティは火から下ろして卵のソースと混ぜます。\n\nパスタは約9分ゆで、グアンチャーレは8分焼き、ソースは卵が固まらないよう火にかけずに1分で仕上げます。4人分です。","category":"主菜","difficulty":"普通","course":"主菜","cuisine":"イタリア料理","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["スパゲッティ カルボナーラ","カルボナーラ レシピ","本場のカルボナーラ","生クリームなし カルボナーラ","カルボナーラ 作り方","グアンチャーレ","ペコリーノ"],"ingredients":[{"name":"卵黄","amount":"4","unit":"","group":"ソース用"},{"name":"全卵","amount":"1","unit":"","group":"ソース用"},{"name":"ペコリーノ・ロマーノ（すりおろし）","amount":"80","unit":"g","group":"ソース用"},{"name":"黒こしょう（挽きたて）","amount":"1","unit":"小さじ","group":"ソース用"},{"name":"スパゲッティ","amount":"400","unit":"g","group":"パスタ用"},{"name":"グアンチャーレ（細切り）","amount":"150","unit":"g","group":"パスタ用"},{"name":"水","amount":"4","unit":"l","group":"パスタ用"},{"name":"粗塩","amount":"40","unit":"g","group":"パスタ用"}],"steps":[{"title":"材料を準備する","content":"グアンチャーレ150gを1cm幅の細切りにし、ペコリーノ・ロマーノ80gをすりおろします。卵黄4個を分け、全卵1個、黒こしょう、スパゲッティ400gを用意します。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"スパゲッティ・カルボナーラ: 材料を準備する"},{"title":"ソースを混ぜる","content":"ボウルに卵黄4個、全卵1個、ペコリーノ・ロマーノ80g、挽きたての黒こしょう小さじ1を入れ、濃いクリーム状になるまで混ぜます。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"スパゲッティ・カルボナーラ: ソースを混ぜる"},{"title":"スパゲッティをゆでる","content":"水4リットルに粗塩40gを加えて沸騰させ、スパゲッティ400gを入れて約9分、アルデンテにゆでます。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"スパゲッティ・カルボナーラ: スパゲッティをゆでる"},{"title":"グアンチャーレを焼く","content":"その間に、大きなフライパンに冷たいままグアンチャーレを油なしで入れ、中弱火で8分、カリッとして脂が出るまで焼きます。火を止めます。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"スパゲッティ・カルボナーラ: グアンチャーレを焼く"},{"title":"ゆで汁を取り分ける","content":"湯を切る前に、ゆで汁をコップ1杯（約200ml）取り分け、スパゲッティの湯を切ります。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"スパゲッティ・カルボナーラ: ゆで汁を取り分ける"},{"title":"グアンチャーレと合わせる","content":"火を止めたままのフライパンにスパゲッティを入れ、30秒ほど混ぜて脂をなじませます。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"スパゲッティ・カルボナーラ: グアンチャーレと合わせる"},{"title":"ソースを加える","content":"卵のソースと取り分けたゆで汁大さじ3を加え、火にかけずにトングで1分混ぜ、固まらずなめらかなクリーム状になるまで仕上げます。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"スパゲッティ・カルボナーラ: ソースを加える"},{"title":"盛り付ける","content":"すぐに深めの皿に盛り、ペコリーノと黒こしょうをさらにかけます。","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"スパゲッティ・カルボナーラ: 盛り付ける"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"スパゲッティ・カルボナーラ"}],"notes":"生クリームは加えません。なめらかさは卵黄、チーズ、ゆで汁から生まれます。卵が固まらないよう、卵を加えるときはフライパンを火から下ろしてください。ソースが固いときは、ゆで汁を少しずつ足します。グアンチャーレが手に入らない場合は熟成パンチェッタでも作れますが、風味は変わります。卵に十分火が通らないレシピです。新鮮な卵を使い、すぐに食べ、妊娠中の方、小さなお子さま、高齢の方、免疫力が低下している方には作らないでください。","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。乾燥スパゲッティ400g、グアンチャーレ150g、卵黄68g（4個）、全卵50g、ペコリーノ・ロマーノ80g、こしょう2g、塩4g（ゆで湯の塩40gの約10%）を使用しています。水は計算に含めていません。","note":"1人分の目安です。グアンチャーレは生のベーコン、ペコリーノ・ロマーノはロマーノチーズを参考値として計算しています。グアンチャーレの脂は一部がフライパンに残っても全量を計算しており、ナトリウム量はグアンチャーレ、チーズ、パスタが吸う塩によって変わります。"},"seo":{"title":"スパゲッティ・カルボナーラの作り方｜生クリームなし | Manual de Cocina","description":"グアンチャーレ、ペコリーノ・ロマーノ、卵黄、黒こしょうで作る生クリームなしのカルボナーラ。4人分、35分で完成。手順を写真付きで解説します。","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"カルボナーラに生クリームは入りますか？","a":"入りません。なめらかさは卵黄、ペコリーノ・ロマーノ、パスタのゆで汁から生まれます。"},{"q":"なぜ卵が固まらないのですか？","a":"火から下ろし、ゆで汁と一緒に混ぜるからです。パスタとフライパンの余熱で、卵が一気に固まらずにソースがまとまります。"},{"q":"グアンチャーレがないときは何を使えばよいですか？","a":"細切りにした熟成パンチェッタが使えます。風味は少し燻製寄りで甘みが控えめですが、作り方は同じです。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b5c0a808-df28-5055-a2c5-5f2ef3f3fe45","recipe_group_id":"659d0428-8876-46ed-a434-50dbc6af42d2","language":"pt","slug":"espaguete-a-carbonara","public_path":"/pt/espaguete-a-carbonara","source_url":null,"title":"Espaguete à carbonara","excerpt":"Espaguete à carbonara com guanciale crocante, pecorino romano, gemas, ovo e pimenta-do-reino preta, sem creme de leite. Para 4 pessoas, pronto em 35 minutos.","summary":"A carbonara é uma massa romana ligada com gemas, ovo, pecorino romano e água do cozimento, sem creme de leite. O guanciale doura na frigideira sem óleo e o espaguete é misturado ao creme de ovos fora do fogo.\n\nA massa cozinha cerca de 9 minutos, o guanciale 8 minutos e o molho termina em 1 minuto, sem fogo, para o ovo não talhar. Rende 4 porções.","category":"Pratos principais","difficulty":"Média","course":"Prato principal","cuisine":"Italiana","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":35,"servings":4,"keywords":["espaguete à carbonara","receita de carbonara","carbonara original","carbonara sem creme de leite","massa carbonara","como fazer carbonara","guanciale e pecorino"],"ingredients":[{"name":"gemas de ovo","amount":"4","unit":"","group":"Para o molho"},{"name":"ovo inteiro","amount":"1","unit":"","group":"Para o molho"},{"name":"pecorino romano ralado","amount":"80","unit":"g","group":"Para o molho"},{"name":"pimenta-do-reino preta moída na hora","amount":"1","unit":"colher de chá","group":"Para o molho"},{"name":"espaguete","amount":"400","unit":"g","group":"Para a massa"},{"name":"guanciale em tiras","amount":"150","unit":"g","group":"Para a massa"},{"name":"água","amount":"4","unit":"l","group":"Para a massa"},{"name":"sal grosso","amount":"40","unit":"g","group":"Para a massa"}],"steps":[{"title":"Prepare os ingredientes","content":"Corte 150 g de guanciale em tiras de cerca de 1 cm e rale 80 g de pecorino romano. Separe 4 gemas e deixe à mão 1 ovo inteiro, a pimenta e 400 g de espaguete.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-01.webp","image_alt":"Espaguete à carbonara: Prepare os ingredientes"},{"title":"Bata o molho","content":"Em uma tigela, bata 4 gemas, 1 ovo inteiro, 80 g de pecorino romano e 1 colher de chá de pimenta-do-reino preta moída na hora até obter um creme grosso.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-02.webp","image_alt":"Espaguete à carbonara: Bata o molho"},{"title":"Cozinhe o espaguete","content":"Leve 4 litros de água com 40 g de sal grosso à fervura, junte 400 g de espaguete e cozinhe cerca de 9 minutos, até ficar al dente.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-03.webp","image_alt":"Espaguete à carbonara: Cozinhe o espaguete"},{"title":"Doure o guanciale","content":"Enquanto isso, coloque o guanciale em uma frigideira grande fria, sem óleo, em fogo médio-baixo e cozinhe por 8 minutos, até ficar crocante e soltar a gordura. Desligue o fogo.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-04.webp","image_alt":"Espaguete à carbonara: Doure o guanciale"},{"title":"Reserve a água do cozimento","content":"Antes de escorrer, reserve 1 copo (cerca de 200 ml) da água do cozimento e escorra o espaguete.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-05.webp","image_alt":"Espaguete à carbonara: Reserve a água do cozimento"},{"title":"Misture com o guanciale","content":"Passe o espaguete para a frigideira com o guanciale, fora do fogo, e misture por 30 segundos para envolver na gordura.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-06.webp","image_alt":"Espaguete à carbonara: Misture com o guanciale"},{"title":"Junte o molho","content":"Despeje o creme de ovos e 3 colheres de sopa da água reservada e misture com a pinça por 1 minuto, sem fogo, até ficar cremoso e sem talhar.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-07.webp","image_alt":"Espaguete à carbonara: Junte o molho"},{"title":"Sirva","content":"Sirva imediatamente em pratos fundos e finalize com mais pecorino e pimenta-do-reino preta.","image_url":"/recetas/espaguetis-a-la-carbonara/paso-08.webp","image_alt":"Espaguete à carbonara: Sirva"}],"image_url":"/recetas/espaguetis-a-la-carbonara/portada.webp","gallery":[{"url":"/recetas/espaguetis-a-la-carbonara/portada.webp","alt":"Espaguete à carbonara"}],"notes":"Não coloque creme de leite: a cremosidade vem das gemas, do queijo e da água da massa. A frigideira deve estar fora do fogo ao juntar o ovo para ele não talhar; se o molho ficar grosso, junte mais água do cozimento aos poucos. Se não encontrar guanciale, use pancetta curada, mas o sabor muda. Leva ovo pouco cozido: use ovos frescos, sirva logo e não prepare para gestantes, crianças pequenas, idosos ou pessoas com imunidade baixa.","nutrition":{"calories":679,"protein_g":28.5,"carbs_g":77,"fat_g":27.7,"sodium_mg":1436,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usa 400 g de espaguete seco, 150 g de guanciale, 68 g de gema (4 gemas), 50 g de ovo inteiro, 80 g de pecorino romano, 2 g de pimenta e 4 g de sal (cerca de 10 % dos 40 g de sal da água do cozimento). A água não é contada.","note":"Estimativa por porção. O guanciale é calculado com bacon cru curado e o pecorino romano com queijo romano, como valores de referência. Toda a gordura do guanciale é contada, mesmo que parte fique na frigideira, e o sódio depende do guanciale, do queijo e do sal que a massa absorve."},"seo":{"title":"Espaguete à carbonara sem creme de leite | Manual de Cocina","description":"Espaguete à carbonara com guanciale, pecorino romano, gemas e pimenta, sem creme de leite. Para 4 pessoas, pronto em 35 minutos. Receita passo a passo.","image_variants":["/recetas/espaguetis-a-la-carbonara/portada-1x1.webp","/recetas/espaguetis-a-la-carbonara/portada-4x3.webp","/recetas/espaguetis-a-la-carbonara/portada-16x9.webp"],"faq":[{"q":"A carbonara leva creme de leite?","a":"Não. A cremosidade vem das gemas, do pecorino romano e de um pouco da água do cozimento da massa."},{"q":"Por que o ovo não talha?","a":"Porque tudo é misturado fora do fogo e com água do cozimento: o calor da massa e da frigideira basta para ligar o molho sem talhar o ovo de uma vez."},{"q":"O que usar se não tiver guanciale?","a":"Pode usar pancetta curada em tiras. O sabor é um pouco mais defumado e menos doce, mas o método é o mesmo."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/espaguetis-a-la-carbonara') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
